# === 樣式 (極簡高留白；iRent 綠為強調色) ===
ACCENT = RGBColor(0x00, 0x79, 0x4D)   # iRent 綠
TEXT   = RGBColor(0x1A, 0x1A, 0x1A)
MUTED  = RGBColor(0x66, 0x66, 0x66)
TITLE_FONT = "Helvetica Neue"
BODY_FONT  = "Helvetica Neue"

def _style_text(text_frame, *, size, bold=False, color=TEXT, align=PP_ALIGN.LEFT):
    for p in text_frame.paragraphs:
        p.alignment = align
        for r in p.runs:
            r.font.name = BODY_FONT
            r.font.size = Pt(size)
            r.font.bold = bold
            r.font.color.rgb = color

def build():
    prs = Presentation()
    prs.slide_width  = Inches(13.333)  # 16:9
    prs.slide_height = Inches(7.5)

    for i, s in enumerate(SLIDES):
        is_title_page = (i == 0) or ("subtitle" in s and not s.get("body"))
        layout = prs.slide_layouts[0 if is_title_page else 5]
        slide = prs.slides.add_slide(layout)

        if slide.shapes.title:
            slide.shapes.title.text = s["title"]
            _style_text(
                slide.shapes.title.text_frame,
                size=44 if is_title_page else 32,
                bold=True, color=ACCENT,
                align=PP_ALIGN.CENTER if is_title_page else PP_ALIGN.LEFT,
            )

        if is_title_page and s.get("subtitle"):
            try:
                ph = slide.placeholders[1]
                ph.text = s["subtitle"]
                _style_text(ph.text_frame, size=22, color=MUTED, align=PP_ALIGN.CENTER)
            except (KeyError, IndexError):
                pass

        if s.get("body"):
            tb = slide.shapes.add_textbox(Inches(0.8), Inches(1.8), Inches(11.7), Inches(5))
            tf = tb.text_frame
            tf.word_wrap = True
            for j, line in enumerate(s["body"]):
                p = tf.paragraphs[0] if j == 0 else tf.add_paragraph()
                p.text = "•  " + line
                p.alignment = PP_ALIGN.LEFT
                p.space_after = Pt(14)
                for r in p.runs:
                    r.font.name = BODY_FONT
                    r.font.size = Pt(24)
                    r.font.color.rgb = TEXT

        if s.get("notes"):
            slide.notes_slide.notes_text_frame.text = s["notes"]

    out = "presentation.pptx"
    prs.save(out)
    print(f"✅ saved {out} — {len(SLIDES)} slides")

if __name__ == "__main__":
    build()
